package net.minecraft.nbt;import java.util.*;public class CompoundTag{public final Map<String,Object> m=new HashMap<>();public boolean contains(String k){return m.containsKey(k);}public void remove(String k){m.remove(k);}public CompoundTag getCompound(String k){return m.get(k) instanceof CompoundTag t?t:new CompoundTag();}public Set<String> getAllKeys(){return m.keySet();}public boolean getBoolean(String k){return Boolean.TRUE.equals(m.get(k));}public void putBoolean(String k,boolean v){m.put(k,v);}public String getString(String k){return (String)m.getOrDefault(k,"");}public void putString(String k,String v){m.put(k,v);}public int getInt(String k){return ((Number)m.getOrDefault(k,0)).intValue();}public void putInt(String k,int v){m.put(k,v);}public long getLong(String k){return ((Number)m.getOrDefault(k,0L)).longValue();}public void putLong(String k,long v){m.put(k,v);}public double getDouble(String k){return ((Number)m.getOrDefault(k,0.)).doubleValue();}public void putDouble(String k,double v){m.put(k,v);}}